//=======================================================================
//
// Modularized from autogenerated Localizable.strings into per-feature namespaces.
// Prefer scoped namespaces (`PledgeStrings`, `ProjectStrings`, `DiscoveryStrings`, etc.)
// for new and agent-authored code to keep context narrow.
//
//=======================================================================

/// Legacy global localization namespace delegating to per-feature namespaces under `Strings/`.
///
/// Available feature namespaces:
/// - `AccessibilityStrings` (61 keys): VoiceOver labels, hints, and accessibility announcements.
/// - `ActivityStrings` (136 keys): Activity feed, social following, and friend connection copy.
/// - `AuthStrings` (141 keys): Login, signup, password reset, two-factor auth, and OAuth copy.
/// - `DashboardStrings` (120 keys): Creator dashboard, Pledged Project Overview, and video feed copy.
/// - `DatesStrings` (76 keys): Relative timestamps, countdowns, and date formatting strings.
/// - `DiscoveryStrings` (143 keys): Discovery browse, categories, filters, sorting, and search copy.
/// - `GeneralStrings` (518 keys): Shared buttons, alerts, tab bar labels, and generic errors.
/// - `MessagesStrings` (57 keys): Creator/backer inbox, message threads, and reply copy.
/// - `PledgeStrings` (295 keys): Pledge flow, rewards, add-ons, shipping, checkout, and payment copy.
/// - `ProfileStrings` (86 keys): User profile, backer modal, surveys, and block-user copy.
/// - `ProjectStrings` (155 keys): Project page, campaign, updates, comments, FAQs, and creator copy.
/// - `SettingsStrings` (41 keys): Account settings, currency preferences, privacy, notifications, and beta tools copy.
public enum Strings {}
